package local.ttlab.gallery;
import android.app.AlertDialog;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Local encrypted-file inventory only; never requests remote media. */
public final class StorageActivity extends SecureActivity {
 private final ExecutorService reader=Executors.newSingleThreadExecutor();private final Handler ui=new Handler(Looper.getMainLooper());private TextView summary,note;private Rows rows;private volatile boolean resumed;private boolean busy;private int epoch;private StorageIndex index;private Future<?> reading;
 private final Runnable next=this::refresh;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(state==null)return;index=new StorageIndex(state.library,state.vault);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(getColor(R.color.gallery_surface));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);ImageButton back=GalleryUi.icon(this,R.drawable.ic_viewer_back,"Volver");back.setOnClickListener(v->finish());top.addView(back);TextView title=GalleryUi.text(this,"Almacenamiento",24,getColor(R.color.gallery_foreground));title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);top.addView(title,new LinearLayout.LayoutParams(0,dp(56),1));title.setGravity(Gravity.CENTER_VERTICAL);ImageButton more=GalleryUi.icon(this,R.drawable.ic_gallery_more,"Opciones de almacenamiento");more.setOnClickListener(v->options());top.addView(more);root.addView(top);
  summary=GalleryUi.text(this,"Leyendo archivos cifrados…",16,getColor(R.color.gallery_foreground));summary.setPadding(dp(20),dp(12),dp(20),dp(12));root.addView(summary);note=GalleryUi.text(this,"",12,getColor(R.color.gallery_muted));note.setPadding(dp(20),0,dp(20),dp(16));root.addView(note);ListView list=new ListView(this);list.setDividerHeight(0);list.setPadding(dp(16),0,dp(16),dp(16));rows=new Rows();list.setAdapter(rows);list.setOnItemClickListener((p,v,n,id)->chat(rows.ids.get(n)));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));content(root);
 }
 @Override protected void onResume(){super.onResume();resumed=true;if(index!=null)index.invalidate();refresh();}@Override void onUnlocked(){refresh();}@Override protected void onPause(){resumed=false;epoch++;if(reading!=null)reading.cancel(true);busy=false;ui.removeCallbacks(next);super.onPause();}@Override protected void onDestroy(){reader.shutdownNow();ui.removeCallbacksAndMessages(null);super.onDestroy();}
 private void refresh(){if(!resumed||state==null||!state.unlocked||busy||isDestroyed())return;busy=true;int request=epoch;reading=reader.submit(()->{try{boolean done=index.scan(4096);StorageIndex.Snapshot snap=index.snapshot();Map<Integer,String> names=new HashMap<>();for(Source.Channel chat:state.library.channels())names.put(chat.id,chat.title);ui.post(()->{if(epoch!=request)return;busy=false;if(!resumed||!state.unlocked||isDestroyed())return;summary.setText(SourceId.label(state.key)+"\nCaché temporal: "+size(snap.cache)+"\nDescargas guardadas: "+size(snap.saved)+"\n\nMiniaturas: "+size(snap.thumbnails)+"\nOriginales: "+size(snap.originals));long unknown=snap.unknownCache+snap.unknownSaved;note.setText("Instantánea local; ⋮ → Actualizar vuelve a medir.\nTamaños cifrados reales. Miniaturas y originales están incluidos en los totales de arriba.\nLímite de caché: "+(state.vault.cacheLimit()/1024/1024)+" MiB. Limpiarla conserva las descargas."+(unknown>0?"\nSin clasificar: "+size(unknown)+(done?". Se asociarán al abrirlos; también pueden ser archivos anteriores sin referencia.":". Clasificando archivos anteriores, sin descargarlos…"):""));rows.data=snap;rows.names=names;rows.ids=new ArrayList<>(snap.chats.keySet());rows.ids.sort((a,b)->Long.compare(snap.chats.get(b).cache+snap.chats.get(b).saved,snap.chats.get(a).cache+snap.chats.get(a).saved));rows.notifyDataSetChanged();if(!done)ui.postDelayed(next,200);});}catch(Exception failure){ui.post(()->{if(epoch!=request)return;busy=false;if(resumed&&!isDestroyed())note.setText("No se pudo leer el almacenamiento. Usa ⋮ → Actualizar para reintentar.");});}});}
 private void options(){GalleryUi.menu(this,"Almacenamiento · "+SourceId.label(state.key),UiSource.isLocal(this)?new String[]{"Actualizar","Límite de caché","Limpiar caché temporal","Videos más pesados"}:new String[]{"Actualizar","Límite de caché","Limpiar caché temporal","Videos más pesados","Quitar todas las descargas"},n->{if(n==0){index.invalidate();refresh();}else if(n==1)GalleryUi.menu(this,"Límite de caché",new String[]{"64 MiB","128 MiB","256 MiB","512 MiB"},k->change(()->state.vault.setCacheLimit((64L<<k)*1024*1024)));else if(n==2)change(()->state.vault.clearCache());else if(n==3)largest(0);else{AlertDialog dialog=new SecureDialogs.Builder(this).setTitle("¿Eliminar todas las descargas?").setMessage("Se borrarán las copias guardadas y la cola de esta fuente. El catálogo, marcas y originales del servicio se conservan.").setNegativeButton("Conservar",null).setPositiveButton("Eliminar",(d,w)->{DownloadService.control(this,state.key,"clear",0,0);ui.postDelayed(()->{index.invalidate();refresh();},700);}).create();trackPrivateDialog(dialog);dialog.show();}});}
 private void chat(int channel){StorageIndex.Usage used=rows.data.chats.get(channel);GalleryUi.menu(this,rows.names.getOrDefault(channel,"Chat "+channel),new String[]{"Limpiar caché de este chat · "+size(used.cache),"Videos más pesados de este chat"},n->{if(n==0)change(()->index.clearChatCache(channel));else largest(channel);});}
 private void largest(int channel){MediaFilter filter=new MediaFilter();filter.channel=channel;filter.type=2;filter.sort=2;startActivity(sourceIntent(MainActivity.class).putExtra("initial-filter",filter.bundle()));}
 private interface Change{void run()throws Exception;}
 private void change(Change action){if(!state.unlocked)return;reader.execute(()->{try{if(!state.unlocked||state.maintenance)return;action.run();index.invalidate();state.media.clearMemory();ui.post(()->{if(!isDestroyed()&&state.unlocked){Toast.makeText(this,"Almacenamiento actualizado",Toast.LENGTH_SHORT).show();refresh();}});}catch(Exception failure){ui.post(()->{if(!isDestroyed())Toast.makeText(this,"No se pudo aplicar. Reintenta.",Toast.LENGTH_LONG).show();});}});}
 private String size(long bytes){return android.text.format.Formatter.formatFileSize(this,bytes);}
 private final class Rows extends BaseAdapter{StorageIndex.Snapshot data;Map<Integer,String> names=Collections.emptyMap();List<Integer> ids=Collections.emptyList();public int getCount(){return ids.size();}public Object getItem(int n){return ids.get(n);}public long getItemId(int n){return ids.get(n);}public View getView(int n,View recycled,ViewGroup parent){int id=ids.get(n);StorageIndex.Usage chat=data.chats.get(id);LinearLayout row=recycled instanceof LinearLayout?(LinearLayout)recycled:new LinearLayout(StorageActivity.this);row.removeAllViews();row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(4),dp(14),dp(4),dp(14));TextView name=GalleryUi.text(StorageActivity.this,names.getOrDefault(id,"Chat "+id),16,getColor(R.color.gallery_foreground));name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(name);row.addView(GalleryUi.text(StorageActivity.this,"Caché "+size(chat.cache)+" · Guardados "+size(chat.saved),13,getColor(R.color.gallery_muted)));row.setContentDescription(name.getText()+". Caché "+size(chat.cache)+", guardados "+size(chat.saved)+". Opciones del chat");return row;}}
}
